type Order = {
  id: Int;
  amount: Int;
  cancelled: Bool;
}

fn filter_active_orders(orders: &Vec[Order]) -> Vec[Order] {
  let result: Vec[Order] = Vec[Order].new();
  let i = 0;
  while i < orders.len() {
    let o = match orders.get(i) { Some(v) => v, None => continue };
    if !o.cancelled {
      result.push(o);
    }
    i = i + 1;
  }
  return result;
}

fn sum_amounts(orders: &Vec[Order]) -> Int {
  let total = 0;
  let i = 0;
  while i < orders.len() {
    let o = match orders.get(i) { Some(v) => v, None => continue };
    total = total + o.amount;
    i = i + 1;
  }
  return total;
}

fn main() -> Int {
  let orders: Vec[Order] = Vec[Order].new();
  orders.push(Order{ id: 1, amount: 30, cancelled: false });
  orders.push(Order{ id: 2, amount: 100, cancelled: true });
  orders.push(Order{ id: 3, amount: 80, cancelled: false });

  let active = filter_active_orders(&orders);
  let total = sum_amounts(&active);
  io.println(string.int_to_str(total));
  return 0;
}
